{"chunk_id":"8ea810","wall_time_seconds":0.000008221,"exit_code":0,"original_token_count":3774,"output":""""Shared closing evaluator: the one check behind every accept and walk-away.

Normal decisions, `agreed`, final offers, "no moves left" and the deadline fallback all close
through `close_decision`. A sheet is eligible when it is in the supplier's latest message of a
live thread, has a price and keeps the must-haves with the supplier's standard terms resolved;
eligible sheets are ranked by complete C (`arena_kit.cost.total_cost`) including the supplier
estimate, if any, and only a sheet below the alternative's C may be accepted.
"""

import math

from arena_kit.cost import closing_terms, must_haves_ok, total_cost
from arena_kit.docs import standard_terms
from arena_kit.play import ENDED, latest, live_threads

from .optimizer import alternative_cost


def supplier_for(estimates, supplier_id, standard):
    """The estimate for `supplier_id` in the shape `total_cost(..., supplier=...)` takes, with the
    quote PDF's standard terms filled in when the estimate has none; None without an estimate."""
    est = (estimates or {}).get(supplier_id)
    if not est:
        return None
    # The current quote is authoritative for fields it establishes; estimate/master
    # defaults remain useful only for fields omitted by this quote.
    effective = {**(est.get("standard") or {}), **(standard or {})}
    return {**est, "standard": effective}


def eligible_sheets(case, events, supplier=None, alternatives=False):
    """[(C, term_sheet_id, terms)] of the supplier's latest message, cheapest first: priced,
    must-haves kept with standard terms resolved, thread not ended. Only the first sheet is the
    standing offer the arena lets us accept ("offer:...-a" alternatives give HTTP 422); with
    `alternatives` the other sheets are included as packages to counter with."""
    if not events:
        return []
    msg = latest(events)
    if msg.get("status") in ENDED:
        return []
    std = standard_terms(events)
    out = []
    sheets = msg.get("term_sheets") or []
    for sheet in sheets if alternatives else sheets[:1]:
        sheet_id, terms = sheet.get("term_sheet_id"), sheet.get("terms") or {}
        if not sheet_id or closing_terms(case, terms, std).get("unit_price") is None:
            continue
        if not must_haves_ok(case, terms, std):
            continue
        c = total_cost(case, terms, std, supplier)
        if math.isfinite(c):
            out.append((c, sheet_id, terms))
    return sorted(out, key=lambda x: (x[0], x[1]))


def best_close(case, threads, estimates=None):
    """(C, supplier_id, term_sheet_id, terms) of the cheapest eligible sheet over all live threads
    that beats the alternative, else None."""
    c_alt = alternative_cost(case)
    best = None
    for sid in live_threads(threads):
        sup = supplier_for(estimates, sid, standard_terms(threads[sid]))
        for c, sheet_id, terms in eligible_sheets(case, threads[sid], sup)[:1]:
            if c < c_alt and (best is None or (c, sid) < best[:2]):
                best = (c, sid, sheet_id, terms)
    return best


def close_decision(case, threads, estimates=None, reason=""):
    """Accept the best eligible sheet across live threads if it beats the alternative, else walk
    away. `estimates`: {supplier_id: supplier estimate for total_cost}. `reason` is for callers'
    traces only."""
    best = best_close(case, threads, estimates)
    if best:
        _, sid, sheet_id, _ = best
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
    live = live_threads(threads) or list(threads)
    return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}


def nonprice(case, terms):
    """The negotiable non-price fields of a term sheet."""
    return {k: terms.get(k) for k in case["negotiable"] if k != "unit_price"}


def same_package(case, a, b, standard=None):
    """True when two sheets close on the same negotiable non-price terms."""
    ta, tb = closing_terms(case, a, standard), closing_terms(case, b, standard)
    return all(ta.get(k) == tb.get(k) for k in case["negotiable"] if k != "unit_price")


def price_for_cost(case, terms, target_c, standard=None, supplier=None, hi=None):
    """Find a positive-price cost root, preferring the branch nearest the reference price.

    Relationship costs can be nonmonotonic in price. Those cases use a bounded scan to find
    feasible brackets; absence of a bracket is reported as ``None`` rather than a guessed zero.
    """
    reference = terms.get("unit_price")
    if not math.isfinite(float(target_c)) or target_c <= 0:
        return None
    upper = float(hi or max(1.0, (reference or 1.0) * 4))
    upper = min(max(upper, 0.01), 1e7)

    def cost(price):
        return total_cost(case, {**terms, "unit_price": price}, standard, supplier)

    # Grow a finite search interval while cost at the upper end remains below target.
    while upper < 1e7 and cost(upper) < target_c:
        upper = min(upper * 2, 1e7)
    lower = 0.01
    if supplier:
        # A bounded grid detects multiple roots and local reversals. Refine every bracket,
        # then choose the root nearest the caller's reference branch.
        count = 10000
        step = (upper - lower) / count
        points = [(lower + i * step, cost(lower + i * step)) for i in range(count + 1)]
        roots = []
        for (x0, y0), (x1, y1) in zip(points, points[1:]):
            if not (math.isfinite(y0) and math.isfinite(y1)) or (y0 - target_c) * (y1 - target_c) > 0:
                continue
            left, right = x0, x1
            increasing = y1 >= y0
            for _ in range(40):
                mid = (left + right) / 2
                if (cost(mid) < target_c) == increasing:
                    left = mid
                else:
                    right = mid
            candidate = (left + right) / 2
            if candidate > 0 and abs(cost(candidate) - target_c) <= max(0.01, abs(target_c) * 1e-8):
                roots.append(candidate)
        return min(roots, key=lambda p: abs(p - (reference or p))) if roots else None

    low_cost = cost(lower)
    high_cost = cost(upper)
    if not (math.isfinite(low_cost) and math.isfinite(high_cost)) or low_cost > target_c or high_cost < target_c:
        return None
    lo, hi = lower, upper
    for _ in range(60):
        mid = (lo + hi) / 2
        if cost(mid) < target_c:
            lo = mid
        else:
            hi = mid
    candidate = (lo + hi) / 2
    return candidate if candidate > 0 and abs(cost(candidate) - target_c) <= max(0.01, abs(target_c) * 1e-8) else None


def revealed_deltas(case, sheets, standard=None):
    """Price differences the supplier reveals between two of its sheets that differ in exactly one
    non-price field: [(field, value_a, value_b, price_b - price_a)]. Sheets differing in several
    fields reveal only a combined package difference and are not listed."""
    out = []
    priced = [s.get("terms") or {} for s in sheets if (s.get("terms") or {}).get("unit_price") is not None]
    for i, a in enumerate(priced):
        for b in priced[i + 1 :]:
            ta, tb = closing_terms(case, a, standard), closing_terms(case, b, standard)
            diff = [k for k in case["negotiable"] if k != "unit_price" and ta.get(k) != tb.get(k)]
            if len(diff) == 1:
                f = diff[0]
                out.append((f, ta.get(f), tb.get(f), round(b["unit_price"] - a["unit_price"], 2)))
    return out
"""Term-sheet economics over the case's term options, using arena_kit.cost.

All values are C in EUR from `arena_kit.cost.total_cost(case, terms, standard, supplier)`.
"""

import itertools
from dataclasses import dataclass, field

from arena_kit.cost import complete_offer, must_haves_ok, total_cost


@dataclass
class Plan:
    c_alt: float  # alternative's C (inf if none)
    c_open: float  # cheapest opening quote's C
    reservation_c: float  # walk-away: never accept above this
    target_c: float  # where we aim
    best_nonprice: dict = field(default_factory=dict)  # cheapest values for non-price fields
    concession_path: list[float] = field(default_factory=list)  # target C per round
    supplier_estimate: dict = field(default_factory=dict)  # full_cost, interest_rate, standard


def plan(case: dict, standard_terms: dict, dossier=None) -> Plan:
    """Reservation, target and concession path. In stabilise/secure_supply, include the
    relationship term with a supplier estimate (should-cost ± sensitivity)."""
    raise NotImplementedError


def meso(case: dict, anchor: dict, c_target: float, n: int = 3) -> list[dict]:
    """n complete term sheets with (nearly) equal C for us but different mixes
    (price-heavy, payment-heavy, term/volume-heavy). Uses arena_kit.cost.complete_offer."""
    raise NotImplementedError


def alternative_cost(case: dict) -> float:
    alt = case["buyer"].get("alternative") or {}
    terms = alt.get("terms") or {}
    return total_cost(case, terms) if terms.get("unit_price") else float("inf")


def best_terms(case: dict, unit_price: float, standard: dict | None = None, supplier=None,
               prefer_longer_lead: bool = False) -> dict:
    """Complete term sheet at `unit_price` whose non-price fields minimise C and keep the
    must-haves. Fields without listed options keep the buyer's plan (`complete_offer`)."""
    base = complete_offer(case, {"unit_price": unit_price})
    options = case.get("term_options") or {}
    fields = [f for f in case["negotiable"] if f != "unit_price" and options.get(f)]
    best, best_c = None, float("inf")
    for combo in itertools.product(*(options[f] for f in fields)):
        terms = {**base, **dict(zip(fields, combo, strict=True))}
        if not must_haves_ok(case, terms, standard):
            continue
        c = total_cost(case, terms, standard, supplier)
        same_cost_longer_lead = (
            prefer_longer_lead and "lead_time_days" in fields and c == best_c
            and terms["lead_time_days"] > best["lead_time_days"]
        )
        if c < best_c or same_cost_longer_lead:
            best, best_c = terms, c
    return best


def payment_breakeven_pct(case: dict, from_days: int, to_days: int) -> float:
    """Exact price discount (%) offsetting the buyer's payment-timing value.

    Payment timing is compared with the case reference term. This preserves the
    complete-cost ratio when neither endpoint is itself the reference term.
    """
    buyer = case["buyer"]
    r = buyer["interest_rate"]
    reference = buyer.get("reference_payment_days", 60)
    from_factor = 1 + r * (reference - from_days) / 360
    to_factor = 1 + r * (reference - to_days) / 360
    if to_factor <= 0:
        raise ValueError("payment term produces a non-positive discount factor")
    return (1 - from_factor / to_factor) * 100
"""Last line of defence before anything is sent (docs/03-playbook.md, universal rules)."""

import re
import math

from arena_kit.cost import closing_terms, must_haves_ok, total_cost
from arena_kit.docs import standard_terms

LEAK_PATTERNS = [
    re.compile(p, re.I)
    for p in (
        r"\bbudget\b",
        r"\btarget price\b",
        r"\burgent(ly)?\b",
        r"\bno (other )?alternative\b",
        r"\bwe (have|need) to (close|sign) (today|quickly|now)\b",
        r"\bour (maximum|limit) is\b",
    )
]


def leaks(body: str) -> list[str]:
    """Phrases that would reveal urgency, budget or a missing alternative."""
    return [p.pattern for p in LEAK_PATTERNS if p.search(body)]


def check(case: dict, move, email: dict, thread_state, facts: dict):
    """Validate one final outgoing action. Raise ValueError instead of repairing its economics."""
    if not isinstance(email, dict):
        raise ValueError("outgoing message must be an object")
    action = email.get("action")
    if action:
        if not isinstance(action, dict) or action.get("type") not in {"accept", "walk_away"}:
            raise ValueError("invalid close action")
        if action["type"] == "accept":
            offer_id = action.get("term_sheet_id")
            found_cost = None
            for sid, events in (thread_state or {}).items():
                from .evaluator import eligible_sheets, supplier_for

                std = standard_terms(events)
                supplier = supplier_for(facts.get("estimates"), sid, std) if isinstance(facts, dict) else None
                match = next((cost for cost, sheet_id, _ in eligible_sheets(case, events, supplier)
                              if sheet_id == offer_id), None)
                if match is not None:
                    found_cost = match
                    break
            from .optimizer import alternative_cost

            if found_cost is None or found_cost >= alternative_cost(case):
                raise ValueError("acceptance must reference a current eligible offer below the alternative")
        return email

    subject, body = email.get("subject", ""), email.get("body", "")
    if not isinstance(subject, str) or not isinstance(body, str):
        raise ValueError("subject and body must be text")
    if len(subject) > 200 or len(body.split()) > 150:
        raise ValueError("outgoing message exceeds subject or body limit")
    if leaks(body):
        raise ValueError("outgoing message reveals private urgency or budget information")
    sheets = email.get("term_sheets") or []
    if not isinstance(sheets, list) or len(sheets) > 3:
        raise ValueError("outgoing message must contain at most three term sheets")
    options = case.get("term_options") or {}
    supplier_id = move if isinstance(move, str) else None
    for sheet in sheets:
        terms = sheet.get("terms") if isinstance(sheet, dict) else None
        if not isinstance(terms, dict):
            raise ValueError("term sheet must contain terms")
        price = terms.get("unit_price")
        if isinstance(price, bool) or not isinstance(price, (int, float)) or not math.isfinite(price) or price <= 0:
            raise ValueError("unit price must be finite and positive")
        if any(key not in case.get("negotiable", []) for key in terms):
            raise ValueError("term sheet contains a field outside the case negotiation schema")
        for field, choices in options.items():
            if field in terms and choices and terms[field] not in choices:
                raise ValueError(f"term sheet has an unsupported {field}")
        events = thread_state.get(move, []) if isinstance(thread_state, dict) else thread_state or []
        std = standard_terms(events)
        from .evaluator import supplier_for

        supplier = supplier_for((facts or {}).get("estimates"), supplier_id, std)
        complete = closing_terms(case, terms, std)
        if not must_haves_ok(case, terms, std):
            raise ValueError("term sheet violates a case must-have")
        cost = total_cost(case, terms, std, supplier)
        if not math.isfinite(cost) or complete.get("unit_price") is None:
            raise ValueError("term sheet does not resolve to complete finite terms")
    return email
